// Augment ultimateExerciseLibrary with primaryMuscle and importance fields

(function augmentLibrary() {

  const coreKeywords = ['squat', 'deadlift', 'bench', 'press', 'row', 'pull-up', 'chin-up', 'dip', 'clean', 'snatch'];

  const specialisedKeywords = ['neck', 'grip', 'wrist', 'toe', 'foot', 'hand', 'finger', 'short foot', 'plate pinch', 'dead hang'];



  for (const group in ultimateExerciseLibrary) {

    ultimateExerciseLibrary[group].forEach(ex => {

      // primaryMuscle: use first element of muscles if exists, otherwise group name

      ex.primaryMuscle = (ex.muscles && ex.muscles.length > 0) ? ex.muscles[0] : group;

      

      // importance: default to 'accessory'

      ex.importance = 'accessory';

      

      // Override to 'core' if name matches core keywords

      const nameLower = ex.name.toLowerCase();

      if (coreKeywords.some(kw => nameLower.includes(kw))) {

        ex.importance = 'core';

      }

      // Override to 'specialised' if name matches specialised keywords

      if (specialisedKeywords.some(kw => nameLower.includes(kw))) {

        ex.importance = 'specialised';

      }

    });

  }

})();

     



